/** Dispatch a layer's matrix by name and index (type aliases cannot be passed around). */
export type Mat<N extends string, L extends number, XP extends Strs, XN extends Strs> = [N, L] extends ["q", 0]
  ? L0_q<XP, XN>
  : [N, L] extends ["k", 0]
  ? L0_k<XP, XN>
  : [N, L] extends ["v", 0]
  ? L0_v<XP, XN>
  : [N, L] extends ["proj", 0]
  ? L0_proj<XP, XN>
  : [N, L] extends ["fc", 0]
  ? L0_fc<XP, XN>
  : [N, L] extends ["mlp", 0]
  ? L0_mlp<XP, XN>
  : [N, L] extends ["q", 1]
  ? L1_q<XP, XN>
  : [N, L] extends ["k", 1]
  ? L1_k<XP, XN>
  : [N, L] extends ["v", 1]
  ? L1_v<XP, XN>
  : [N, L] extends ["proj", 1]
  ? L1_proj<XP, XN>
  : [N, L] extends ["fc", 1]
  ? L1_fc<XP, XN>
  : [N, L] extends ["mlp", 1]
  ? L1_mlp<XP, XN>
  : [N, L] extends ["q", 2]
  ? L2_q<XP, XN>
  : [N, L] extends ["k", 2]
  ? L2_k<XP, XN>
  : [N, L] extends ["v", 2]
  ? L2_v<XP, XN>
  : [N, L] extends ["proj", 2]
  ? L2_proj<XP, XN>
  : [N, L] extends ["fc", 2]
  ? L2_fc<XP, XN>
  : [N, L] extends ["mlp", 2]
  ? L2_mlp<XP, XN>
  : [N, L] extends ["q", 3]
  ? L3_q<XP, XN>
  : [N, L] extends ["k", 3]
  ? L3_k<XP, XN>
  : [N, L] extends ["v", 3]
  ? L3_v<XP, XN>
  : [N, L] extends ["proj", 3]
  ? L3_proj<XP, XN>
  : [N, L] extends ["fc", 3]
  ? L3_fc<XP, XN>
  : [N, L] extends ["mlp", 3]
  ? L3_mlp<XP, XN>
  : never;


